import React, { useCallback, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_LIVEBOARD_ID } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';

export default function DashboardHome() {
  const [embedError, setEmbedError] = useState<string | null>(null);
  const { hiddenActions, disabledActions, tier } = useTier();

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    const msg =
      err?.data?.errorMessage ||
      err?.message ||
      (typeof err === 'object' ? JSON.stringify(err) : String(err));
    setEmbedError(msg);
    console.error('[ThoughtSpot Liveboard Dashboard]', err);
  }, []);

  return (
    <div style={{ minHeight: '100%', backgroundColor: '#F9FAFB', display: 'flex', flexDirection: 'column' }}>
      <div style={{ padding: '2rem 2.5rem 0' }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#2c313c', margin: 0 }}>Dashboard</h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '8px 0 0', maxWidth: 640 }}>
          Welcome to RedFlagAlert. Below is your primary liveboard. Use the sidebar for Search, Portfolios, and
          Analytics (including Data Bot on Pro). You are on the <strong style={{ color: '#2c313c' }}>{tier}</strong>{' '}
          access level — change it under <em>Access level (demo)</em> to see different embed capabilities.
        </p>
      </div>

      <div style={{ padding: '1.25rem 2.5rem 2rem', flex: 1, display: 'flex', flexDirection: 'column' }}>
        {embedError && (
          <div
            role="alert"
            style={{
              marginBottom: '1rem',
              padding: '0.75rem 1rem',
              background: '#FEF2F2',
              border: '1px solid #FECACA',
              borderRadius: 8,
              fontSize: 14,
              color: '#991B1B',
            }}
          >
            <strong>Embed error:</strong> {embedError}
          </div>
        )}

        <div
          style={{
            backgroundColor: '#ffffff',
            borderRadius: 12,
            border: '1px solid #E5E7EB',
            overflow: 'hidden',
            flex: 1,
            minHeight: 'min(640px, calc(100vh - 260px))',
          }}
        >
          <LiveboardEmbed
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            fullHeight
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            onError={onError}
            isLiveboardStylingAndGroupingEnabled
            additionalFlags={{ enable2ColumnLayout: true }}
            style={{ width: '100%', minHeight: 'calc(100vh - 260px)' }}
          />
        </div>
      </div>
    </div>
  );
}
